      (value) => ({ ok: true as const, value }),
      (error: unknown) => ({ ok: false as const, error }),
    );
    return operation;
  };
  const waitEntered = async () => {
    if (!operation) throw new Error("operation not started");
    let timer: ReturnType<typeof setTimeout> | undefined;
    try {
