          timer = setTimeout(() => reject(new Error("held wait entry guard")), 1000);
        }),
      ]);
    } finally {
      clearTimeout(timer);
    }
  };
  const cleanup = async (failures: unknown[]) => {
    controller.abort();
    latch.resolve();
    if (operation) await operation;
    try {
      await close();
    } catch (error) {
      failures.push(error);
    }
    const outcome = await closed;
    if (!outcome.ok) failures.push(outcome.error);
  };
  return {
    service,
