    expect(retained.page.next).toBe(null);
    expect(retained.context.scopePosition).toBe("pos-2");
    expect(groupReads).toBeGreaterThan(0);
    groupReads = 0;
    const retainedMinimum = {
      scopeEpoch: retained.context.scopeEpoch,
